import pprint
from pathlib import Path

import torch
import torch.nn.functional as F
import transformers
from accelerate import infer_auto_device_map, init_empty_weights
from accelerate.utils import is_xpu_available
from transformers import (
    AutoConfig,
    AutoModel,
    AutoModelForCausalLM,
    AutoModelForSeq2SeqLM,
    AutoTokenizer,
    BitsAndBytesConfig,
    LogitsProcessor
)

import modules.shared as shared
from modules.logging_colors import logger
from modules.text_generation import get_reply_from_output_ids
from modules.torch_utils import get_device

transformers.logging.set_verbosity_error()


class _StopEverythingStoppingCriteria(transformers.StoppingCriteria):
    def __init__(self):
        transformers.StoppingCriteria.__init__(self)

    def __call__(self, input_ids: torch.LongTensor, _scores: torch.FloatTensor) -> bool:
        return shared.stop_everything


class Stream(transformers.StoppingCriteria):
    def __init__(self, callback_func=None):
        self.callback_func = callback_func

    def __call__(self, input_ids, scores) -> bool:
        if self.callback_func is not None:
            self.callback_func(input_ids[0])

        return False


class LogitsBiasProcessor(LogitsProcessor):
    def __init__(self, logit_bias=None):
        self.logit_bias = logit_bias if logit_bias is not None else {}
        if self.logit_bias:
            self.keys = list([int(key) for key in self.logit_bias.keys()])
            values = [self.logit_bias[str(key)] for key in self.keys]
            self.values = torch.tensor(values, dtype=torch.float, device=shared.model.device)

    def __call__(self, input_ids: torch.LongTensor, logits: torch.FloatTensor) -> torch.FloatTensor:
        if self.logit_bias:
            logits[0, self.keys] += self.values

        return logits

    def __repr__(self):
        return f"<{self.__class__.__name__}(logit_bias={self.logit_bias})>"


class LogprobProcessor(LogitsProcessor):
    def __init__(self, logprobs=None):
        self.logprobs = logprobs
        self.token_alternatives = {}
        self.token_alternatives_history = []

    def __call__(self, input_ids: torch.LongTensor, logits: torch.FloatTensor) -> torch.FloatTensor:
        if self.logprobs is not None:  # 0-5
            log_e_probabilities = F.log_softmax(logits, dim=1)
            top_values, top_indices = torch.topk(log_e_probabilities, k=self.logprobs)
            top_tokens = [get_reply_from_output_ids([tok]) for tok in top_indices[0]]
            top_probs = [float(x) for x in top_values[0]]
            self.token_alternatives = dict(zip(top_tokens, top_probs))
            self.token_alternatives_history.append(self.token_alternatives)

        return logits

    def __repr__(self):
        return f"<{self.__class__.__name__}(logprobs={self.logprobs}, token_alternatives={self.token_alternatives})>"


def load_tokenizer(model_name, tokenizer_dir=None):
    if tokenizer_dir:
        path_to_model = Path(tokenizer_dir)
    else:
        path_to_model = Path(f"{shared.args.model_dir}/{model_name}/")

    tokenizer = None
    if path_to_model.exists():
        if shared.args.no_use_fast:
            logger.info('Loading the tokenizer with use_fast=False.')

        tokenizer = AutoTokenizer.from_pretrained(
            path_to_model,
            trust_remote_code=shared.original_args.trust_remote_code,
            use_fast=not shared.args.no_use_fast
        )

    return tokenizer


def load_model_HF(model_name):
    torch._dynamo.config.disable = True

    path_to_model = Path(f'{shared.args.model_dir}/{model_name}')
    params = {
        'low_cpu_mem_usage': True,
        'attn_implementation': shared.args.attn_implementation,
    }

    if shared.original_args.trust_remote_code:
        params['trust_remote_code'] = True

    if shared.args.force_safetensors:
        params['force_safetensors'] = True

    config = AutoConfig.from_pretrained(path_to_model, trust_remote_code=shared.original_args.trust_remote_code)

    # Determine torch_dtype: respect --bf16 flag, otherwise autodetect
    # from model config, but never allow float32.
    if shared.args.bf16:
        params['torch_dtype'] = torch.bfloat16
    else:
        dtype = getattr(config, 'torch_dtype', None) or getattr(getattr(config, 'text_config', None), 'torch_dtype', None)
        if dtype in (torch.float16, torch.bfloat16):
            params['torch_dtype'] = dtype
        else:
            params['torch_dtype'] = torch.float16

    if 'chatglm' in model_name.lower():
        LoaderClass = AutoModel
    else:
        if config.to_dict().get('is_encoder_decoder', False):
            LoaderClass = AutoModelForSeq2SeqLM
            shared.is_seq2seq = True
        else:
            LoaderClass = AutoModelForCausalLM

    # Determine if we should use default loading
    should_use_default_loading = not any([
        shared.args.cpu,
        shared.args.load_in_8bit,
        shared.args.load_in_4bit,
        shared.args.disk,
        shared.args.cpu_memory is not None,
    ])

    # Load the model without any special settings
    if should_use_default_loading:
        params['device_map'] = 'auto'

        logger.info("TRANSFORMERS_PARAMS=")
        pprint.PrettyPrinter(indent=4, sort_dicts=False).pprint(params)
        print()

        model = LoaderClass.from_pretrained(path_to_model, **params)
        if not (hasattr(model, 'is_loaded_in_4bit') and model.is_loaded_in_4bit):
            device = get_device()
            if device:
                model = model.to(device)

    # Load with quantization and/or offloading
    else:
        if not any((shared.args.cpu, torch.cuda.is_available(), is_xpu_available(), torch.backends.mps.is_available())):
            logger.warning('torch.cuda.is_available() and is_xpu_available() returned False. This means that no GPU has been detected. Falling back to CPU mode.')
            shared.args.cpu = True

        if shared.args.cpu:
            params['torch_dtype'] = torch.float32
        else:
            params['device_map'] = 'auto'
            if x := get_max_memory_dict():
                params['max_memory'] = x

            if shared.args.load_in_4bit:
                # See https://github.com/huggingface/transformers/pull/23479/files
                # and https://huggingface.co/blog/4bit-transformers-bitsandbytes
                quantization_config_params = {
                    'load_in_4bit': True,
                    'bnb_4bit_compute_dtype': eval(f"torch.{shared.args.compute_dtype}") if shared.args.compute_dtype in ["bfloat16", "float16", "float32"] else None,
                    'bnb_4bit_quant_type': shared.args.quant_type,
                    'bnb_4bit_use_double_quant': shared.args.use_double_quant,
                    'llm_int8_enable_fp32_cpu_offload': True
                }
                params['quantization_config'] = BitsAndBytesConfig(**quantization_config_params)

            elif shared.args.load_in_8bit:
                if shared.args.gpu_split:
                    params['quantization_config'] = BitsAndBytesConfig(load_in_8bit=True, llm_int8_enable_fp32_cpu_offload=True)
                else:
                    params['quantization_config'] = BitsAndBytesConfig(load_in_8bit=True)

                if params.get('max_memory') is not None:
                    with init_empty_weights():
                        model = LoaderClass.from_config(config, trust_remote_code=params.get('trust_remote_code'))

                    model.tie_weights()
                    params['device_map'] = infer_auto_device_map(
                        model,
                        dtype=torch.int8,
                        max_memory=params.get('max_memory'),
                        no_split_module_classes=model._no_split_modules
                    )

            if shared.args.disk:
                params['offload_folder'] = str(Path(shared.args.disk_cache_dir))

        logger.info("TRANSFORMERS_PARAMS=")
        pprint.PrettyPrinter(indent=4, sort_dicts=False).pprint(params)
        print()
        model = LoaderClass.from_pretrained(path_to_model, **params)

    return model


def get_max_memory_dict():
    max_memory = {}
    if shared.args.cpu_memory > 0:
        max_memory['cpu'] = f'{shared.args.cpu_memory}GiB'

    if shared.args.gpu_split:
        for i, memory in enumerate(shared.args.gpu_split.split(',')):
            max_memory[i] = f'{memory}GiB'

    return max_memory if len(max_memory) > 0 else None

# Editor

All of the behaviors, content and state of a Slate editor is rolled up into a single, top-level `Editor` object. It has an interface of:

```typescript
interface Editor {
  // Current editor state
  children: Node[]
  selection: Range | null
  operations: Operation[]
  marks: Omit<Text, 'text'> | null
  // Schema-specific node behaviors.
  isInline: (element: Element) => boolean
  isVoid: (element: Element) => boolean
  markableVoid: (element: Element) => boolean
  normalizeNode: (entry: NodeEntry) => void
  onChange: (options?: { operation?: Operation }) => void
  // Overrideable core actions.
  addMark: (key: string, value: any) => void
  apply: (operation: Operation) => void
  deleteBackward: (unit: 'character' | 'word' | 'line' | 'block') => void
  deleteForward: (unit: 'character' | 'word' | 'line' | 'block') => void
  deleteFragment: () => void
  insertBreak: () => void
  insertSoftBreak: () => void
  insertFragment: (fragment: Node[]) => void
  insertNode: (node: Node) => void
  insertText: (text: string) => void
  removeMark: (key: string) => void
}
```

It is slightly more complex than the others, because it contains all of the top-level functions that define your custom, domain-specific behaviors.

The `children` property contains the document tree of nodes that make up the editor's content.

The `selection` property contains the user's current selection, if any.
Don't set it directly; use [Transforms.select](04-transforms.md#selection-transforms)

The `operations` property contains all of the operations that have been applied since the last "change" was flushed. \(Since Slate batches operations up into ticks of the event loop.\)

The `marks` property stores formatting to be applied when the editor inserts text. If `marks` is `null`, the formatting will be taken from the current selection.
Don't set it directly; use `Editor.addMark` and `Editor.removeMark`.

## Overriding Behaviors

In previous guides we've already hinted at this, but you can override any of the behaviors of an editor by overriding its function properties.

For example, if you want to define link elements that are inline nodes:

```javascript
const { isInline } = editor

editor.isInline = element => {
  return element.type === 'link' ? true : isInline(element)
}
```

Or maybe you want to override the `insertText` behavior to "linkify" URLs:

```javascript
const { insertText } = editor

editor.insertText = text => {
  if (isUrl(text)) {
    // ...
    return
  }

  insertText(text)
}
```

If you have void "mention" elements that can accept marks like bold or italic:

```javascript
const { isVoid, markableVoid } = editor

editor.isVoid = element => {
  return element.type === 'mention' ? true : isVoid(element)
}

editor.markableVoid = element => {
  return element.type === 'mention' || markableVoid(element)
}
```

Or you can even define custom "normalizations" that take place to ensure that links obey certain constraints:

```javascript
const { normalizeNode } = editor

editor.normalizeNode = (entry, options) => {
  const [node, path] = entry

  if (Element.isElement(node) && node.type === 'link') {
    // ...
    return
  }

  normalizeNode(entry, options)
}
```

Whenever you override behaviors, be sure to call the existing functions as a fallback mechanism for the default behavior. Unless you really do want to completely remove the default behaviors \(which is rarely a good idea\).

> 🤖 For more info, check out the [Editor Instance Methods to Override API Reference](../api/nodes/editor.md#schema-specific-instance-methods-to-override)

## Helper Functions

The `Editor` interface, like all Slate interfaces, exposes helper functions that are useful when implementing certain behaviors. There are many, many editor-related helpers. For example:

```javascript
// Get the start point of a specific node at path.
const point = Editor.start(editor, [0, 0])

// Get the fragment (a slice of the document) at a range.
const fragment = Editor.fragment(editor, range)
```

There are also many iterator-based helpers, for example:

```javascript
// Iterate over every node in a range.
for (const [node, path] of Editor.nodes(editor, { at: range })) {
  // ...
}

// Iterate over every point in every text node in the current selection.
for (const point of Editor.positions(editor)) {
  // ...
}
```

> 🤖 For more info, check out the [Editor Static Methods API Reference](../api/nodes/editor.md#static-methods)

import { removeNode } from "trix/core/helpers"

import * as config from "trix/config"
import BasicObject from "trix/core/basic_object"

import { defer, handleEvent, makeElement, tagName, triggerEvent } from "trix/core/helpers"
const { lang, css, keyNames } = config

const undoable = function(fn) {
  return function() {
    const commands = fn.apply(this, arguments)
    commands.do()
    if (!this.undos) {
      this.undos = []
    }
    this.undos.push(commands.undo)
  }
}

export default class AttachmentEditorController extends BasicObject {
  constructor(attachmentPiece, element, container, options = {}) {
    super(...arguments)
    this.didClickToolbar = this.didClickToolbar.bind(this)
    this.didClickActionButton = this.didClickActionButton.bind(this)
    this.didKeyDownCaption = this.didKeyDownCaption.bind(this)
    this.didInputCaption = this.didInputCaption.bind(this)
    this.didChangeCaption = this.didChangeCaption.bind(this)
    this.didBlurCaption = this.didBlurCaption.bind(this)
    this.attachmentPiece = attachmentPiece
    this.element = element
    this.container = container
    this.options = options
    this.attachment = this.attachmentPiece.attachment
    if (tagName(this.element) === "a") {
      this.element = this.element.firstChild
    }
    this.install()
  }

  install() {
    this.makeElementMutable()
    this.addToolbar()
    if (this.attachment.isPreviewable()) {
      this.installCaptionEditor()
    }
  }

  uninstall() {
    let undo = this.undos.pop()
    this.savePendingCaption()
    while (undo) {
      undo()
      undo = this.undos.pop()
    }
    this.delegate?.didUninstallAttachmentEditor(this)
  }

  // Private

  savePendingCaption() {
    if (this.pendingCaption != null) {
      const caption = this.pendingCaption
      this.pendingCaption = null
      if (caption) {
        this.delegate?.attachmentEditorDidRequestUpdatingAttributesForAttachment?.({ caption }, this.attachment)
      } else {
        this.delegate?.attachmentEditorDidRequestRemovingAttributeForAttachment?.("caption", this.attachment)
      }
    }
  }

  // Installing and uninstalling

  makeElementMutable = undoable(() => {
    return {
      do: () => {
        this.element.dataset.trixMutable = true
      },
      undo: () => delete this.element.dataset.trixMutable,
    }
  })

  addToolbar = undoable(() => {
    // <div class="#{css.attachmentMetadataContainer}" data-trix-mutable="true">
    //   <div class="trix-button-row">
    //     <span class="trix-button-group trix-button-group--actions">
    //       <button type="button" class="trix-button trix-button--remove" title="#{lang.remove}" data-trix-action="remove">#{lang.remove}</button>
    //     </span>
    //   </div>
    // </div>
    const element = makeElement({
      tagName: "div",
      className: css.attachmentToolbar,
      data: { trixMutable: true },
      childNodes: makeElement({
        tagName: "div",
        className: "trix-button-row",
        childNodes: makeElement({
          tagName: "span",
          className: "trix-button-group trix-button-group--actions",
          childNodes: makeElement({
            tagName: "button",
            className: "trix-button trix-button--remove",
            textContent: lang.remove,
            attributes: { title: lang.remove },
            data: { trixAction: "remove" },
          }),
        }),
      }),
    })

    if (this.attachment.isPreviewable()) {
      // <div class="#{css.attachmentMetadataContainer}">
      //   <span class="#{css.attachmentMetadata}">
      //     <span class="#{css.attachmentName}" title="#{name}">#{name}</span>
      //     <span class="#{css.attachmentSize}">#{size}</span>
      //   </span>
      // </div>
      element.appendChild(
        makeElement({
          tagName: "div",
          className: css.attachmentMetadataContainer,
          childNodes: makeElement({
            tagName: "span",
            className: css.attachmentMetadata,
            childNodes: [
              makeElement({
                tagName: "span",
                className: css.attachmentName,
                textContent: this.attachment.getFilename(),
                attributes: { title: this.attachment.getFilename() },
              }),
              makeElement({
                tagName: "span",
                className: css.attachmentSize,
                textContent: this.attachment.getFormattedFilesize(),
              }),
            ],
          }),
        })
      )
    }

    handleEvent("click", { onElement: element, withCallback: this.didClickToolbar })
    handleEvent("click", {
      onElement: element,
      matchingSelector: "[data-trix-action]",
      withCallback: this.didClickActionButton,
    })

    triggerEvent("trix-attachment-before-toolbar", { onElement: this.element, attributes: { toolbar: element, attachment: this.attachment } })

    return {
      do: () => this.element.appendChild(element),
      undo: () => removeNode(element),
    }
  })

  installCaptionEditor = undoable(() => {
    const textarea = makeElement({
      tagName: "textarea",
      className: css.attachmentCaptionEditor,
      attributes: { placeholder: lang.captionPlaceholder },
      data: { trixMutable: true },
    })
    textarea.value = this.attachmentPiece.getCaption()

    const textareaClone = textarea.cloneNode()
    textareaClone.classList.add("trix-autoresize-clone")
    textareaClone.tabIndex = -1

    const autoresize = function() {
      textareaClone.value = textarea.value
      textarea.style.height = textareaClone.scrollHeight + "px"
    }

    handleEvent("input", { onElement: textarea, withCallback: autoresize })
    handleEvent("input", { onElement: textarea, withCallback: this.didInputCaption })
    handleEvent("keydown", { onElement: textarea, withCallback: this.didKeyDownCaption })
    handleEvent("change", { onElement: textarea, withCallback: this.didChangeCaption })
    handleEvent("blur", { onElement: textarea, withCallback: this.didBlurCaption })

    const figcaption = this.element.querySelector("figcaption")
    const editingFigcaption = figcaption.cloneNode()

    return {
      do: () => {
        figcaption.style.display = "none"
        editingFigcaption.appendChild(textarea)
        editingFigcaption.appendChild(textareaClone)
        editingFigcaption.classList.add(`${css.attachmentCaption}--editing`)
        figcaption.parentElement.insertBefore(editingFigcaption, figcaption)
        autoresize()
        if (this.options.editCaption) {
          return defer(() => textarea.focus())
        }
      },
      undo() {
        removeNode(editingFigcaption)
        figcaption.style.display = null
      },
    }
  })

  // Event handlers

  didClickToolbar(event) {
    event.preventDefault()
    return event.stopPropagation()
  }

  didClickActionButton(event) {
    const action = event.target.getAttribute("data-trix-action")
    switch (action) {
      case "remove":
        return this.delegate?.attachmentEditorDidRequestRemovalOfAttachment(this.attachment)
    }
  }

  didKeyDownCaption(event) {
    if (keyNames[event.keyCode] === "return") {
      event.preventDefault()
      this.savePendingCaption()
      return this.delegate?.attachmentEditorDidRequestDeselectingAttachment?.(this.attachment)
    }
  }

  didInputCaption(event) {
    this.pendingCaption = event.target.value.replace(/\s/g, " ").trim()
  }

  didChangeCaption(event) {
    return this.savePendingCaption()
  }

  didBlurCaption(event) {
    return this.savePendingCaption()
  }
}

